"""Finite Gemma geometry witnesses; independent logical and wire-format anchors.

The activation pattern is integral with max127. Canonical packing must therefore
produce exact d=(row+1), s=96*(row+1) and the known signed bytes. No oracle reads
production packed buffers. The full-vocabulary case proves extent/ownership;
nonzero Q8 numerical behavior is checked separately at N256.
"""
from pathlib import Path
import struct
ROOT = Path(__file__).parent
HEADER = '// Copyright 2026 AMD ROCm Software\n// SPDX-License-Identifier: MIT\n// Generated by gemma3_fixtures.py; independent exact anchors.\n'
X = list(range(-16, 15)) + [127]
Q5 = [((j * 7 + 5) % 32) - 16 for j in range(32)]
Q8 = [((j * 7 + 3) % 31) - 15 for j in range(32)]
assert len(X) == 32 and sum(X) == 96 and max(map(abs, X)) == 127

def encode_q5(codes):
    assert all(-16 <= c <= 15 for c in codes)
    unsigned = [c + 16 for c in codes]
    qh = sum(((v >> 4) & 1) << j for j, v in enumerate(unsigned))
    return qh.to_bytes(4, 'little') + bytes((unsigned[j] & 15) | ((unsigned[j+16] & 15) << 4) for j in range(16))

def decode_q5(payload):
    # Independent byte-oriented logical decoder, not production vector addressing.
    return [((payload[4+j % 16] >> (4 if j >= 16 else 0)) & 15)
            + (16 if payload[j // 8] & (1 << (j % 8)) else 0) - 16 for j in range(32)]

assert decode_q5(encode_q5(Q5)) == Q5
assert set(Q5) == set(range(-16, 16))
for d in (-0.125, 0.03125, 0.5):
    wire = struct.pack('<e', d) + encode_q5(Q5)
    assert len(wire) == 22
    assert [struct.unpack('<e', wire[:2])[0] * v for v in decode_q5(wire[2:])] == [d*v for v in Q5]

cases = [(6,1152,n,r,False) for n in (256,1024,6912) for r in (1,3)]
cases += [(6,1152,49,1,False)]
cases += [(8,1152,256,3,False),(8,1152,262144,1,True),
          (12,1024,1152,3,False),(12,6912,1152,3,False),(14,6912,1152,3,False)]
cases = [case + ('mixed',) for case in cases]
cases += [(6,1152,49,1,False,'zero'), (6,1152,49,1,False,'tie')]
text = [HEADER, (ROOT.parent/'interface.loom').read_text()]
for fmt in ('q5_0','q8_0','q4k','q5k','q6k'):
    text.append(f'config.def @ggml.linear_{fmt}_q8_1_x4.token_capacity = 8 : index\nconfig.def @ggml.linear_{fmt}_q8_1_x4.output_capacity = 262144 : index\n')
text.append('config.def @ggml.quantize_q8_1_x4.group_capacity = 524288 : index\n')
text.append('kernel.decl @ggml_quantize_q8_1_x4_f32(%rows:index,%width:index) launch(%capacity:index,%width:index,%input:buffer,%packed:buffer)\n')
for fmt in ('q5_0','q8_0','q4k','q6k'):
    text.append(f'kernel.decl @ggml_linear_{fmt}_q8_1_x4(%rows:index,%width:index,%cols:index) launch(%capacity:index,%width:index,%cols:index,%packed:buffer,%weight:buffer,%output:buffer)\n')
# All test input/expected values arise from mathematical constants. Initializers
# encode owned fixture bytes only; actual leaf/wrapper inputs remain immutable.
for tag,K,N,R,zero_weights,mode in cases:
    name=f'gemma3_q{tag}_k{K}_n{N}_r{R}_{mode}'
    codes_x = [0]*32 if mode=='zero' else ([x+(1 if 16<=j<31 else 0) for j,x in enumerate(X)] if mode=='tie' else X)
    packed_scale = 0 if mode=='zero' else 1
    packed_sum = sum(codes_x)
    block,bs={6:(32,22),8:(32,34),12:(256,144),14:(256,210)}[tag]
    W=K//block*bs*N; P=R*K//128*144; fmt={6:'q5_0',8:'q8_0',12:'q4k',14:'q6k'}[tag]
    text.append(f'func.def @{name}.init(%input:buffer,%weight:buffer) {{\n  %o = index.constant 0 : offset\n  %zero = index.constant 0 : index\n  %one = index.constant 1 : index\n  %nr = index.constant {R} : index\n  %nk = index.constant {K} : index\n  %n32 = index.constant 32 : index\n  %n31 = index.constant 31 : index\n  %raw = buffer.view %input[%o] : buffer -> view<{R}x{K}xf32>\n  scf.for %r = [%zero to %nr step %one] {{\n    %rp = index.add %r, %one : index\n    %ri = index.cast %rp : index to i32\n    %rf = scalar.uitofp %ri : i32 to f32\n    scf.for %k = [%zero to %nk step %one] {{\n      %j = index.rem %k, %n32 : index\n      %ji = index.cast %j : index to i32\n      %sixteen = scalar.constant 16 : i32\n      %centered = scalar.subi %ji, %sixteen : i32\n      %last = index.cmp eq, %j, %n31 : index\n      %max = scalar.constant 127 : i32\n      %code = scf.select %last, %max, %centered : i32\n      %cf = scalar.sitofp %code : i32 to f32\n      %x = scalar.mulf %cf, %rf : f32\n      view.store %x, %raw[%r,%k] : f32, view<{R}x{K}xf32>\n    }}\n  }}\n')
    if mode=='zero':
        text[-1] = text[-1].replace('%x = scalar.mulf %cf, %rf : f32','%x = scalar.constant 0.0 : f32')
    elif mode=='tie':
        text[-1] = text[-1].replace('%x = scalar.mulf %cf, %rf : f32', '%half = scalar.constant 0.5 : f32\n      %shift = scalar.addf %cf, %half : f32\n      %tied = scf.select %last, %cf, %shift : f32\n      %x = scalar.mulf %tied, %rf : f32')
    if not zero_weights:
        text.append(f'  %nc = index.constant {N} : index\n  %nb = index.constant {K//block} : index\n  %four = index.constant 4 : index\n  %three = index.constant 3 : index\n  %two = index.constant 2 : index\n  %stride = index.constant {bs} : offset\n  %rowstride = index.constant {K//block*bs} : offset\n  scf.for %c = [%zero to %nc step %one] {{\n    %cm = index.rem %c, %four : index\n    %cp = index.add %cm, %one : index\n    %ci = index.cast %cp : index to i32\n    %cf = scalar.uitofp %ci : i32 to f32\n    %row = index.scale %c, %rowstride : index, offset -> offset\n    scf.for %b = [%zero to %nb step %one] {{\n      %bo = index.scale %b, %stride : index, offset -> offset\n      %base = index.add %row, %bo : offset\n      %bytes = buffer.view %weight[%base] : buffer -> view<{bs}xi8>\n')
        if tag in (6,8):
            payload=encode_q5(Q5) if tag==6 else bytes(x&255 for x in Q8)
            pattern=bytes(2)+payload
        elif tag==12:
            pattern=bytes(4)+bytes([1]*8)+bytes([17]*4)+bytes([51]*128)
        else:
            pattern=bytes([51]*128+[170]*64+[1]*16+[0]*2)
        assert len(pattern)==bs
        # Static wire bytes avoid coupling encoder arithmetic to the device decoder.
        for j,v in enumerate(pattern):
            text.append(f'      %v{j} = scalar.constant {v if v<128 else v-256} : i8\n      view.store %v{j}, %bytes[{j}] : i8, view<{bs}xi8>\n')
        if tag in (6,8):
            text.append('      %bm = index.rem %b, %three : index\n      %bp = index.add %bm, %one : index\n      %bi = index.cast %bp : index to i32\n      %bf = scalar.uitofp %bi : i32 to f32\n      %ds0 = scalar.mulf %cf, %bf : f32\n      %unit = scalar.constant 0.03125 : f32\n      %ds1 = scalar.mulf %ds0, %unit : f32\n      %parity = index.rem %c, %two : index\n      %negative = index.cmp eq, %parity, %one : index\n      %neg = scalar.negf %ds1 : f32\n      %scale = scf.select %negative, %neg, %ds1 : f32\n')
        else:text.append('      %unit = scalar.constant 0.5 : f32\n      %scale = scalar.mulf %cf, %unit : f32\n')
        text.append(f'      %add = index.constant {208 if tag==14 else 0} : offset\n      %do = index.add %base, %add : offset\n      %d = buffer.view %weight[%do] : buffer -> view<1xf16>\n      %dh = scalar.fptrunc %scale : f32 to f16\n      view.store %dh, %d[0] : f16, view<1xf16>\n')
        if tag==12:text.append('      %min = scalar.constant 0.25 : f16\n      %mh = buffer.view %weight[%base] : buffer -> view<2xf16>\n      view.store %min, %mh[1] : f16, view<2xf16>\n')
        text.append('    }\n  }\n')
    text.append('  func.return\n}\n')
    args='%count:buffer,%input:buffer,%weight:buffer,%p0:buffer,%p1:buffer,%y0:buffer,%y1:buffer'
    text.append(f'command.program.def @{name}.actual() launch({args}) {{\n')
    for key,v in [('policy',1),('tag',tag),('r',R),('k',K),('n',N),('wb',W),('begin',0)]:text.append(f'  %{key} = index.constant {v} : index\n')
    text.append('  %o = index.constant 0 : offset\n  %fixed = scalar.constant -1 : i32\n  %w = buffer.view %weight[%o] : buffer -> view<[%wb]xi8>\n')
    text.append('  kernel.launch @ggml_quantize_q8_1_x4_f32[%r,%k](%r,%k,%input,%p0) : [index,index](index,index,buffer,buffer)\n  template.apply<@llm.projection.pack_input>(%policy,%r,%r,%k,%begin,%fixed,%o,%count,%input,%p1) : (index,index,index,index,index,i32,offset,buffer,buffer,buffer)\n')
    text.append(f'  kernel.launch @ggml_linear_{fmt}_q8_1_x4[%r,%k,%n](%r,%k,%n,%p0,%w,%y0) : [index,index,index](index,index,index,buffer,view<[%wb]xi8>,buffer)\n')
    text.append('  template.apply<@llm.projection.project_packed>(%policy,%tag,%r,%r,%k,%n,%wb,%begin,%fixed,%o,%count,%p1,%w,%y1) : (index,index,index,index,index,index,index,index,i32,offset,buffer,buffer,view<[%wb]xi8>,buffer)\n  command.return\n}\n')
    text.append(f'func.def @{name}.expected({args}) {{\n  %o = index.constant 0 : offset\n  %z = index.constant 0 : index\n  %one = index.constant 1 : index\n  %rn = index.constant {R} : index\n  %gn = index.constant {K//128} : index\n  %cn = index.constant {N} : index\n  %four = index.constant 4 : index\n  %gstride = index.constant 144 : offset\n')
    for which in (0,1):
        text.append(f'  %out{which} = buffer.view %y{which}[%o] : buffer -> view<{R}x{N}xf32>\n')
    text.append('  scf.for %r = [%z to %rn step %one] {\n')
    # Independent CPU-computed exact per-row/column-mod4 results.
    for r in range(R):
        text.append(f'    %ir{r} = index.constant {r} : index\n    %isr{r} = index.cmp eq, %r, %ir{r} : index\n    scf.if %isr{r} {{\n')
        text.append('      scf.for %g = [%z to %gn step %one] {\n        %rg = index.mul %r, %gn : index\n        %group = index.add %rg, %g : index\n        %go = index.scale %group, %gstride : index, offset -> offset\n')
        text.append('        %always = scalar.constant true : i1\n')
        for which in (0,1):
            text.append('        scf.if %always {\n')
            text.append(f'        %meta{which} = buffer.view %p{which}[%go] : buffer -> view<8xf16>\n        %codes{which} = buffer.view %p{which}[%go] : buffer -> view<144xi8>\n')
            for j in range(8):
                v=(r+1)*(packed_scale if j%2==0 else packed_sum)
                text.append(f'        %md{which}_{j} = scalar.constant {v}.0 : f16\n        view.store %md{which}_{j}, %meta{which}[{j}] : f16, view<8xf16>\n')
            # Store the independent known signed pattern in each of four logical
            # 32-value payload chunks; ds metadata precedes the128signed bytes.
            text.append('        %payload_end = index.constant 128 : index\n        %logical32 = index.constant 32 : index\n        %last31 = index.constant 31 : index\n        %bias16 = scalar.constant 16 : i32\n        %max127 = scalar.constant 127 : i32\n        %header16 = index.constant 16 : index\n        scf.for %j = [%z to %payload_end step %one] {\n          %logical = index.rem %j, %logical32 : index\n          %ji = index.cast %logical : index to i32\n          %centered = scalar.subi %ji, %bias16 : i32\n          %last = index.cmp eq, %logical, %last31 : index\n          %code32 = scf.select %last, %max127, %centered : i32\n          %code = scalar.trunci %code32 : i32 to i8\n          %dest = index.add %j, %header16 : index\n')
            if mode=='zero':
                text[-1]=text[-1].replace('%code = scalar.trunci %code32 : i32 to i8','%code = scalar.constant 0 : i8')
            elif mode=='tie':
                text[-1]=text[-1].replace('%code = scalar.trunci %code32 : i32 to i8', '%sixteen_index = index.constant 16 : index\n          %positive = index.cmp uge, %logical, %sixteen_index : index\n          %inc = scalar.constant 1 : i32\n          %raised = scalar.addi %code32, %inc : i32\n          %increment = scalar.andi %positive, %last : i1\n          %notlast = scalar.xori %increment, %positive : i1\n          %tiedcode = scf.select %notlast, %raised, %code32 : i32\n          %code = scalar.trunci %tiedcode : i32 to i8')
            text.append(f'          view.store %code, %codes{which}[%dest] : i8, view<144xi8>\n        }}\n        }}\n')
        text.append('      }\n')
        text.append('      scf.for %c = [%z to %cn step %one] {\n        %cm = index.rem %c, %four : index\n')
        for c in range(4):
            if zero_weights:expected=0.
            elif tag in (6,8):
                codes=Q5 if tag==6 else Q8
                dot=sum(x*y for x,y in zip(codes_x,codes))
                expected=sum(dot*(r+1)*(c+1)*(b%3+1)/32*(-1 if c%2 else 1) for b in range(K//32))
            else:expected=(K//32)*sum(codes_x)*(r+1)*(1.5*(c+1)-(0.25 if tag==12 else 0))
            text.append(f'        %ic{c} = index.constant {c} : index\n        %isc{c} = index.cmp eq, %cm, %ic{c} : index\n        scf.if %isc{c} {{\n          %v{c} = scalar.constant {float(expected)!r} : f32\n')
            for which in (0,1):text.append(f'          view.store %v{c}, %out{which}[%r,%c] : f32, view<{R}x{N}xf32>\n')
            text.append('        }\n')
        text.append('      }\n    }\n')
    text.append('  }\n  func.return\n}\n')
    text.append(f'check.scenario @{name} {{\n  check.trial[1](%trial:index,%entropy:check.entropy) {{\n    %count = check.generate.fill value({R}) : tensor<3xi32>\n    %input_owner = check.generate.fill value(-101.0) : tensor<{R*K+4}xf32>\n    %input = check.tensor.view %input_owner offset(8) : tensor<{R*K+4}xf32> -> tensor<{R*K}xf32>\n    %weight_owner = check.generate.fill value({0 if zero_weights else -67}) : tensor<{W+512}xi8>\n    %weight = check.tensor.view %weight_owner offset(256) : tensor<{W+512}xi8> -> tensor<{W}xi8>\n    check.generate<@{name}.init>(%input,%weight) : (tensor<{R*K}xf32>,tensor<{W}xi8>) -> ()\n')
    for which in (0,1):text.append(f'    %p{which}_owner = check.generate.fill value(-77) : tensor<{P+512}xi8>\n    %p{which} = check.tensor.view %p{which}_owner offset(256) : tensor<{P+512}xi8> -> tensor<{P}xi8>\n    %y{which}_owner = check.generate.fill value(-999.0) : tensor<{R*N+4}xf32>\n    %y{which} = check.tensor.view %y{which}_owner offset(8) : tensor<{R*N+4}xf32> -> tensor<{R*N}xf32>\n')
    text.append(f'    check.compare<@{name}.actual,@{name}.expected>(%count,%input,%weight,%p0,%p1,%y0,%y1) : (tensor<3xi32>,tensor<{R*K}xf32>,tensor<{W}xi8>,tensor<{P}xi8>,tensor<{P}xi8>,tensor<{R*N}xf32>,tensor<{R*N}xf32>) -> () {{\n')
    for n,t in [('count','3xi32'),('input_owner',f'{R*K+4}xf32'),('weight_owner',f'{W+512}xi8')]+[(f'p{w}_owner',f'{P+512}xi8') for w in (0,1)]+[(f'y{w}_owner',f'{R*N+4}xf32') for w in (0,1)]:text.append(f'      check.expect.bitwise actual(%{n}) expected(%{n}) : tensor<{t}>\n')
    text.append('    }\n  }\n  check.return\n}\n')
(ROOT/'gemma3_checks.loom').write_text(''.join(text))
